<?php
namespace Tests\Feature;
use App\Models\Announcement; use App\Models\Attendance; use App\Models\SchoolClass; use App\Models\Student; use App\Models\Teacher; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SchoolManagementTest extends TestCase { use RefreshDatabase;
    public function test_public_landing_page_is_available(): void { $this->get('/')->assertOk()->assertSee('Northstar Academy')->assertSee('Enter the dashboard'); }
    public function test_staff_can_access_the_panel_and_all_resource_pages(): void { $user=User::factory()->create(); $this->actingAs($user); foreach(['/admin','/admin/students','/admin/teachers','/admin/school-classes','/admin/attendances','/admin/announcements'] as $path) { $response = $this->get($path); $this->assertSame(200, $response->status(), $path . ' :: ' . ($response->exception?->getMessage() ?? 'no exception')); } }
    public function test_school_relationships_and_dashboard_counts_are_grounded_in_data(): void { $teacher=Teacher::factory()->create(); $class=SchoolClass::create(['teacher_id'=>$teacher->id,'name'=>'Year 7 · Maple','grade_level'=>'Year 7','room_number'=>'B101','capacity'=>28]); $student=Student::factory()->create(['school_class_id'=>$class->id]); $attendance=Attendance::create(['student_id'=>$student->id,'date'=>now()->toDateString(),'status'=>'present']); Announcement::create(['title'=>'Test','body'=>'Body']); $this->assertSame($class->id,$student->fresh()->schoolClass->id); $this->assertSame($student->id,$attendance->fresh()->student->id); $this->assertDatabaseHas('students',['id'=>$student->id,'school_class_id'=>$class->id]); }
    public function test_attendance_cannot_be_recorded_twice_for_the_same_student_and_day(): void { $student=Student::factory()->create(); Attendance::create(['student_id'=>$student->id,'date'=>'2026-08-31','status'=>'present']); $this->expectException(\Illuminate\Database\UniqueConstraintViolationException::class); Attendance::create(['student_id'=>$student->id,'date'=>'2026-08-31','status'=>'late']); }
}